function nextGreater(nums) {
  const answer = nums.map(() => -1), stack = [] //@init
  for (let i = 0; i < nums.length; i++) { //@loop
    while (stack.length && nums[stack[stack.length - 1]] < nums[i]) { //@check
      answer[stack.pop()] = nums[i] //@pop
    }
    stack.push(i) //@push
  }
  return answer //@done
}

