def solve(nums):
    answer = [-1] * len(nums)  # -1 means no bigger value to the right
    stack = []  # indexes still waiting, values falling from bottom to top
    for i, x in enumerate(nums):
        while stack and nums[stack[-1]] < x:
            answer[stack.pop()] = x  # x is the first bigger value for that index
        stack.append(i)  # i now waits for its own answer
    return answer

