  const spans = []
  const stack = [] // indexes of days with higher prices, nearest on top
  for (let i = 0; i < prices.length; i++) {
    // Pop every day whose price is not higher than prices[i].
    const start = stack.length ? stack[stack.length - 1] : -1
    spans.push(i - start)
    stack.push(i)
  }
  return spans
}

